css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: none;

  background: transparent !important;
  pointer-events: none;
}

.motor-panel-widget,
.motor-panel-widget * {
  box-sizing: border-box;
  pointer-events: none;
}

.motor-panel-widget {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  background: transparent;
  opacity: var(--w-opacity, 1);
  user-select: none;
}

.motor-panel-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  shape-rendering: geometricPrecision;
}

.mp-title,
.mp-label,
.mp-section-title,
.mp-button-text {
  font-family:
    Bahnschrift,
    "DIN Alternate",
    "Segoe UI",
    Arial,
    sans-serif;

  font-style: normal;
  dominant-baseline: central;
}

.mp-title {
  fill: #246875;
  font-size: 19px;
  font-weight: 600;
  letter-spacing: 0.3px;
  text-anchor: middle;
}

.mp-label {
  fill: #30485C;
  font-size: 14px;
  font-weight: 500;
  text-anchor: start;
}

.mp-section-title {
  fill: #246875;
  font-size: 16px;
  font-weight: 600;
  text-anchor: start;
}

.mp-unit {
  font-family:
    "IBM Plex Mono",
    Consolas,
    "Liberation Mono",
    monospace;

  fill: #0A638F;
  font-size: 14px;
  font-weight: 600;
  text-anchor: middle;
  dominant-baseline: central;
}

.mp-field {
  fill: url("#mp-field");
  stroke: #65778C;
  stroke-width: 1;

  filter: drop-shadow(
    0 0.8px 0.6px rgba(34, 49, 65, 0.10)
  );
}

.mp-panel-outline {
  fill: none;
  stroke: #B5C4CF;
  stroke-width: 1;
}

.mp-separator {
  fill: none;
  stroke: #CDD7DF;
  stroke-width: 0.8;
  opacity: 0.7;
}

.mp-button {
  fill: url("#mp-button");
  stroke: #819CAA;
  stroke-width: 1;

  filter: drop-shadow(
    0 1px 0.8px rgba(34, 49, 65, 0.12)
  );
}

.mp-button-text {
  fill: #345A6C;
  font-size: 11px;
  font-weight: 600;
  text-anchor: middle;
}

.mp-button-multiline {
  font-size: 10px;
  letter-spacing: 0.1px;
}

.mp-reflection {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 1;
  stroke-linecap: round;
  opacity: 0.5;
}

.mp-motor-part {
  fill: url("#mp-motor");
  stroke: #01524F;
  stroke-width: 1.3;
  stroke-linejoin: round;
}

.mp-motor-line {
  fill: none;
  stroke: #01524F;
  stroke-width: 1.1;
  stroke-linecap: round;
}

.mp-motor-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 0.9;
  stroke-linecap: round;
  opacity: 0.55;
}

.mp-unit-divider {
  fill: none;
  stroke: #8193A3;
  stroke-width: 0.8;
}

js:
"use strict";

(function () {
  const DEFAULT_TITLE = "MOTOR";
  const BASE_FONT_SIZE = 19;
  const MAX_TITLE_WIDTH = 536;

  let titleElement = null;
  let svgElement = null;
  let latestWidget = window.WIDGET || {};

  function fitTitle() {
    if (!titleElement) {
      return;
    }

    titleElement.style.fontSize = BASE_FONT_SIZE + "px";

    const textWidth = titleElement.getComputedTextLength();

    if (textWidth > MAX_TITLE_WIDTH) {
      const size =
        BASE_FONT_SIZE * MAX_TITLE_WIDTH / textWidth;

      titleElement.style.fontSize = size + "px";
    }
  }

  function render(widget) {
    if (!titleElement || !svgElement) {
      return;
    }

    const name =
      typeof widget.name === "string"
        ? widget.name.trim()
        : "";

    const title = name || DEFAULT_TITLE;

    titleElement.textContent = title;
    svgElement.setAttribute(
      "aria-label",
      "Panel visual de motor: " + title
    );

    fitTitle();
  }

  window.onWidgetUpdate = function (widget) {
    latestWidget = widget || {};
    render(latestWidget);
  };

  function initialize() {
    titleElement = document.getElementById("mp-title");
    svgElement = document.querySelector(".motor-panel-svg");

    render(latestWidget);

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(fitTitle);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }

  /*
   * Solo el título se actualiza desde NOMBRE.
   * Sin variables del PLC ni acciones de control.
   * Todos los campos de datos permanecen vacíos.
   */
})();
